const people=document.querySelector('#person'),month=document.querySelector('#month');
const fields={number:document.querySelector('#invoiceNumber'),date:document.querySelector('#invoiceDate'),seller:document.querySelector('#sellerId'),total:document.querySelector('#totalAmount'),net:document.querySelector('#netAmount')};
const ui={video:document.querySelector('#video'),canvas:document.querySelector('#canvas'),state:document.querySelector('#scanState'),empty:document.querySelector('#cameraEmpty'),start:document.querySelector('#startScan'),image:document.querySelector('#imageInput'),list:document.querySelector('#recordList'),emptyList:document.querySelector('#emptyState'),count:document.querySelector('#rowCount'),summary:document.querySelector('#summaryPreview'),typeHint:document.querySelector('#typeHint'),export:document.querySelector('#exportXls'),toast:document.querySelector('#toast')};
let stream=null,raf=0,lastRaw='',rightRaw='';
let records=JSON.parse(localStorage.getItem('invoice-expense-records')||'[]');
const scriptUrl=document.querySelector('#scriptUrl'),databaseState=document.querySelector('#databaseState');
scriptUrl.value=localStorage.getItem('invoice-expense-script-url')||'';

function buildMonths(){const now=new Date();for(let offset=-14;offset<=3;offset++){const d=new Date(now.getFullYear(),now.getMonth()+offset,1);const roc=d.getFullYear()-1911;const mm=String(d.getMonth()+1).padStart(2,'0');const opt=new Option(`民國 ${roc} 年 ${mm} 月`,`${roc}${mm}`);if(offset===0)opt.selected=true;month.add(opt)}}
function money(v){return v===''?'—':Number(v).toLocaleString('zh-TW')}
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');setTimeout(()=>ui.toast.classList.remove('show'),2200)}
function selectedType(){return document.querySelector('input[name="expenseType"]:checked')?.value||''}
function setType(value,automatic=false){const el=document.querySelector(`input[name="expenseType"][value="${value}"]`);if(el){el.checked=true;ui.typeHint.textContent=automatic?`已自動判斷為「${value}」；仍可手動修改`:'已手動選擇費用類別';updatePreview()}}
function classify(raw){const t=raw.toLowerCase();if(/停車|parking|park fee|車位/.test(t))return'停車費用';if(/汽油|柴油|油品|加油|無鉛|公升|liter|gasoline|diesel|中油|台塑/.test(t))return'加油費用';return''}
function updatePreview(){document.querySelector('#pNumber').textContent=fields.number.value||'—';document.querySelector('#pDate').textContent=fields.date.value||'—';document.querySelector('#pTotal').textContent=money(fields.total.value);document.querySelector('#pNet').textContent=money(fields.net.value);const summary=people.value&&selectedType()?`${people.value}${selectedType()}－${month.value}`:'請先選擇登錄者與費用類別';ui.summary.textContent=summary}
function parseLeft(raw){const s=raw.trim();if(!/^[A-Z]{2}\d{8}\d{7}\d{4}[0-9a-f]{16}/i.test(s))return false;const sales=parseInt(s.slice(21,29),16),total=parseInt(s.slice(29,37),16);fields.number.value=s.slice(0,10).toUpperCase();fields.date.value=s.slice(10,17);fields.total.value=Number.isFinite(total)?total:'';fields.net.value=Number.isFinite(sales)?sales:'';fields.seller.value=s.slice(45,53);const type=classify(s.slice(77));if(type)setType(type,true);updatePreview();return true}
function acceptCode(raw){if(!raw||raw===lastRaw)return;lastRaw=raw;setTimeout(()=>{lastRaw=''},1200);if(parseLeft(raw)){ui.state.textContent='已讀取左側，再掃右側';ui.state.className='status live';toast('已讀取發票基本資料');return}rightRaw=raw;const type=classify(raw);if(type){setType(type,true);ui.state.textContent='左右 QR Code 已完成';ui.state.className='status done';stopCamera();toast(`已辨識為${type}`)}else{ui.state.textContent='已讀取明細，請確認類別';ui.state.className='status done';stopCamera();toast('明細已讀取，請手動確認類別')}}
async function startCamera(){if(!window.jsQR){toast('掃描元件載入失敗');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false});ui.video.srcObject=stream;await ui.video.play();ui.empty.classList.add('hidden');ui.state.textContent='掃描中';ui.state.className='status live';ui.start.textContent='停止掃描';scanLoop()}catch(e){toast('無法開啟相機，請允許權限或改用照片辨識')}}
function stopCamera(){cancelAnimationFrame(raf);if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;ui.video.srcObject=null;ui.empty.classList.remove('hidden');ui.start.textContent='開啟相機掃描'}
function scanLoop(){if(!stream)return;const v=ui.video,c=ui.canvas;if(v.readyState===v.HAVE_ENOUGH_DATA){const max=900,scale=Math.min(1,max/v.videoWidth);c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(v,0,0,c.width,c.height);const im=x.getImageData(0,0,c.width,c.height),code=jsQR(im.data,im.width,im.height,{inversionAttempts:'attemptBoth'});if(code)acceptCode(code.data)}raf=requestAnimationFrame(scanLoop)}
async function scanImage(file){const img=await createImageBitmap(file);const c=ui.canvas,max=1800,scale=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,c.width,c.height);const im=x.getImageData(0,0,c.width,c.height);let found=0;for(let i=0;i<4;i++){const code=jsQR(im.data,im.width,im.height,{inversionAttempts:'attemptBoth'});if(!code)break;acceptCode(code.data);found++;const loc=code.location;const minX=Math.max(0,Math.min(loc.topLeftCorner.x,loc.bottomLeftCorner.x)-12),minY=Math.max(0,Math.min(loc.topLeftCorner.y,loc.topRightCorner.y)-12),maxX=Math.min(c.width,Math.max(loc.topRightCorner.x,loc.bottomRightCorner.x)+12),maxY=Math.min(c.height,Math.max(loc.bottomLeftCorner.y,loc.bottomRightCorner.y)+12);x.fillStyle='white';x.fillRect(minX,minY,maxX-minX,maxY-minY);im.data.set(x.getImageData(0,0,c.width,c.height).data)}if(!found)toast('照片中未辨識到 QR Code，請靠近並保持清晰');else toast(`已讀取 ${found} 個 QR Code`)}
function valid(){if(!people.value)return'請選擇登錄者';if(!month.value)return'請選擇登錄月份';if(!selectedType())return'請確認加油或停車費用';if(!/^[A-Z]{2}\d{8}$/.test(fields.number.value.toUpperCase().replace('-','')))return'發票號碼格式不正確';if(!/^\d{7}$/.test(fields.date.value))return'發票日期請輸入民國7碼';if(!/^\d{8}$/.test(fields.seller.value))return'賣方統編應為8碼';if(fields.total.value==='')return'請輸入憑證總金額';if(fields.net.value==='')return'請輸入未稅金額';return''}
async function sendToSheet(record){const url=scriptUrl.value.trim();if(!url)return false;databaseState.textContent='同步中…';databaseState.className='database-state syncing';try{await fetch(url,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(record)});databaseState.textContent='已連接並同步';databaseState.className='database-state connected';return true}catch(e){databaseState.textContent='同步失敗，資料已留在手機';databaseState.className='database-state error';return false}}
async function addRecord(){const err=valid();if(err){toast(err);return}const n=fields.number.value.toUpperCase().replace('-','');if(records.some(r=>r.invoice===n)){toast('這張發票已在清單中');return}const record={seller:fields.seller.value,format:'25',invoice:n,date:fields.date.value,total:Number(fields.total.value),account:'621310',net:Number(fields.net.value),department:'03900',summary:`${people.value}${selectedType()}－${month.value}`,registrant:people.value,expenseType:selectedType(),entryMonth:month.value,createdAt:new Date().toISOString()};records.push(record);save();const synced=await sendToSheet(record);resetInvoice();toast(synced?'已儲存並同步到試算表':'已儲存在手機，可直接匯出')}
function resetInvoice(){Object.values(fields).forEach(f=>f.value='');document.querySelectorAll('input[name="expenseType"]').forEach(x=>x.checked=false);rightRaw='';ui.state.textContent='尚未掃描';ui.state.className='status';ui.typeHint.textContent='掃描後自動判斷，必要時可手動修改';updatePreview()}
function save(){localStorage.setItem('invoice-expense-records',JSON.stringify(records));render()}
function render(){ui.list.innerHTML='';records.forEach((r,i)=>{const el=document.createElement('article');el.className='record';el.innerHTML=`<div><strong>${escapeHtml(r.summary)}</strong><span>${r.invoice} ・ ${r.date} ・ $${money(r.total)}</span></div><button type="button" aria-label="刪除第 ${i+1} 筆">×</button>`;el.querySelector('button').onclick=()=>{records.splice(i,1);save()};ui.list.append(el)});ui.emptyList.hidden=records.length>0;ui.count.textContent=records.length;ui.export.disabled=!records.length}
function escapeHtml(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function exportXls(){const headers=['賣方統一編號','憑證格式','憑證號碼','憑證日期','憑證總金額','會計科目','未稅金額','費用歸屬部門','摘要'];const rows=records.map(r=>[r.seller,r.format,r.invoice,r.date,r.total,r.account,r.net,r.department,r.summary]);const textCols=new Set([0,1,2,3,5,7]);const table=`<table><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr>${rows.map(row=>`<tr>${row.map((v,i)=>`<td${textCols.has(i)?' style="mso-number-format:\\@"':''}>${escapeHtml(v)}</td>`).join('')}</tr>`).join('')}</table>`;const html=`<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8"></head><body>${table}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`pay_${month.value}.xls`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已匯出 Excel 檔')}

buildMonths();render();updatePreview();
ui.start.onclick=()=>stream?stopCamera():startCamera();ui.image.onchange=e=>e.target.files[0]&&scanImage(e.target.files[0]).catch(()=>toast('照片讀取失敗'));document.querySelector('#addRecord').onclick=addRecord;ui.export.onclick=exportXls;document.querySelector('#clearAll').onclick=()=>{if(records.length&&confirm('確定清除所有待匯出資料？')){records=[];save()}};
[people,month,...Object.values(fields)].forEach(el=>el.addEventListener('input',()=>{if(el===fields.total&&fields.total.value!==''&&!fields.net.value)fields.net.value=Math.round(Number(fields.total.value)/1.05);updatePreview()}));document.querySelectorAll('input[name="expenseType"]').forEach(el=>el.addEventListener('change',()=>{ui.typeHint.textContent='已手動選擇費用類別';updatePreview()}));
window.addEventListener('pagehide',stopCamera);
function updateDatabaseState(){if(scriptUrl.value.trim()){databaseState.textContent='已設定試算表';databaseState.className='database-state connected'}else{databaseState.textContent='尚未連接';databaseState.className='database-state'}}
document.querySelector('#saveScriptUrl').onclick=()=>{const url=scriptUrl.value.trim();if(url&&!/^https:\/\/script\.google\.com\/(?:macros\/s|a\/macros\/[^/]+\/s)\/.+\/exec$/i.test(url)){toast('網址格式不正確，請貼上 Apps Script /exec 網址');return}localStorage.setItem('invoice-expense-script-url',url);updateDatabaseState();toast(url?'試算表網址已儲存':'已改為只儲存在手機')};
updateDatabaseState();
